/**
 * Browser-safe client helpers for consuming an A2UI-enabled Genkit agent.
 *
 * This module has NO Node dependencies. It builds on Genkit's agent client
 * (`remoteAgent` from `genkit/beta/client`), filters A2UI parts out of the
 * agent stream, and hands whole envelopes to whatever renderer you use (e.g.
 * `@a2ui/web_core`'s `MessageProcessor`).
 *
 * @module
 */

import { remoteAgent } from 'genkit/beta/client';
import { a2uiEnvelopesFromParts, a2uiPart } from './part.mjs';
import type { A2uiClientAction, A2uiServerEnvelope } from './types.mjs';

export { a2uiEnvelopesFromParts, a2uiPart, isA2uiPart } from './part.mjs';
export {
  A2UI_MIME_TYPE,
  A2UI_VERSION,
  BASIC_CATALOG_ID,
  type A2uiClientAction,
  type A2uiComponent,
  type A2uiEnvelope,
  type A2uiPart,
  type A2uiServerEnvelope,
  type ActionEnvelope,
} from './types.mjs';

/** A single event yielded while streaming an A2UI agent turn. */
export type A2uiStreamEvent =
  | { type: 'text'; text: string }
  | { type: 'envelopes'; envelopes: A2uiServerEnvelope[] };

/** Options for {@link streamA2uiAgent}. */
export interface StreamA2uiAgentOptions {
  /** URL of the Genkit agent/flow endpoint (e.g. `/uiAgent`). */
  url: string;
  /** The user message to send (Genkit message data or a plain string). */
  message: string | Record<string, unknown>;
  /** Server-managed session id (a UUID). */
  sessionId?: string;
  /** Extra HTTP headers. */
  headers?: Record<string, string>;
  /** Abort signal to cancel the request. */
  abortSignal?: AbortSignal;
}

/** Normalizes a string message into a Genkit user message. */
function toMessage(message: string | Record<string, unknown>) {
  if (typeof message === 'string') {
    // `as const` keeps `role` as the literal `'user'` rather than widening to
    // `string`, so the result is assignable to an agent input `message`.
    return { role: 'user' as const, content: [{ text: message }] };
  }
  return message;
}

/**
 * Streams an A2UI-enabled Genkit agent, yielding prose text deltas and complete
 * A2UI envelope batches in the order they arrive. Feed the envelopes to your
 * renderer's message processor.
 *
 * @example
 * ```ts
 * import { MessageProcessor } from '@a2ui/web_core/v0_9';
 * import { basicCatalog } from '@a2ui/lit/v0_9';
 * import { streamA2uiAgent } from '@genkit-ai/a2ui/client';
 *
 * const processor = new MessageProcessor([basicCatalog]);
 * for await (const ev of streamA2uiAgent({ url: '/uiAgent', message: 'weather in Tokyo' })) {
 *   if (ev.type === 'text') appendProse(ev.text);
 *   else processor.processMessages(ev.envelopes);
 * }
 * ```
 */
export async function* streamA2uiAgent(
  options: StreamA2uiAgentOptions
): AsyncGenerator<A2uiStreamEvent, void, unknown> {
  const agent = remoteAgent({ url: options.url, headers: options.headers });
  // A server-managed session id (when provided) attaches this turn to an
  // existing conversation; otherwise the agent starts a fresh session.
  const chat = agent.chat(
    options.sessionId ? { sessionId: options.sessionId } : undefined
  );

  const turn = chat.sendStream(
    { message: toMessage(options.message) } as Parameters<
      typeof chat.sendStream
    >[0],
    { abortSignal: options.abortSignal }
  );

  for await (const chunk of turn.stream) {
    if (chunk.text) {
      yield { type: 'text', text: chunk.text };
    }
    // A2UI rides as data parts on the raw chunk; extract whole envelopes.
    const envelopes = a2uiEnvelopesFromParts(chunk.raw.modelChunk?.content);
    if (envelopes.length > 0) {
      yield { type: 'envelopes', envelopes };
    }
  }
  // Surface any server error / finalize the turn.
  await turn.response;
}

/**
 * Builds the agent input for sending a rendered surface's user action back to
 * the agent as the next turn. The action's `name` becomes the user message so
 * the agent can react to it; the full action object is attached as an a2ui data
 * part for richer handling.
 */
export function actionToMessage(action: A2uiClientAction) {
  if (!action) {
    throw new Error('actionToMessage: action is required');
  }
  const summary =
    `User interacted with the UI (surface "${action.surfaceId}"): ` +
    `action "${action.name}"` +
    (action.context && Object.keys(action.context).length
      ? ` with context ${JSON.stringify(action.context)}`
      : '') +
    '.';
  return {
    // `as const` keeps `role` as the literal `'user'` rather than widening to
    // `string`, so the result is assignable to an agent input `message`.
    role: 'user' as const,
    content: [{ text: summary }, a2uiPart([{ action }])],
  };
}
